import gurobipy
from gurobipy import GRB

def solve_problem():
    data = CSVQA_DATA
    table = None
    for t in data.get('tables', []):
        if t.get('table_id') == 'file_0_view_0':
            table = t
            break
    if table is None:
        raise ValueError('Table file_0_view_0 not found')
    records = table.get('records', [])
    I = []
    r_i = {}
    d_i = {}
    s_i = {}
    for rec in records:
        vals = rec.get('values', {})
        prod = vals.get('Product Name')
        if prod is None:
            continue
        I.append(prod)
        rev_str = vals.get('Revenue')
        if rev_str is None:
            raise ValueError(f'Missing Revenue for product {prod}')
        try:
            rev = float(rev_str)
        except Exception as e:
            raise ValueError(f'Invalid Revenue for product {prod}: {rev_str}') from e
        r_i[prod] = rev
        dem_str = vals.get('Demand')
        if dem_str is None:
            raise ValueError(f'Missing Demand for product {prod}')
        try:
            dem = int(dem_str)
        except Exception as e:
            raise ValueError(f'Invalid Demand for product {prod}: {dem_str}') from e
        d_i[prod] = dem
        inv_str = vals.get('Initial Inventory')
        if inv_str is None:
            raise ValueError(f'Missing Initial Inventory for product {prod}')
        try:
            inv = int(inv_str)
        except Exception as e:
            raise ValueError(f'Invalid Initial Inventory for product {prod}: {inv_str}') from e
        s_i[prod] = inv
    if set(I) != set(r_i.keys()):
        missing = set(I) - set(r_i.keys())
        raise ValueError(f'Missing revenue for products: {missing}')
    if set(I) != set(d_i.keys()):
        missing = set(I) - set(d_i.keys())
        raise ValueError(f'Missing demand for products: {missing}')
    if set(I) != set(s_i.keys()):
        missing = set(I) - set(s_i.keys())
        raise ValueError(f'Missing inventory for products: {missing}')
    model = gurobipy.Model()
    model.setParam('MIPGap', 1e-06)
    x = model.addVars(I, lb=0, vtype=GRB.CONTINUOUS, name='')
    model.setObjective(gurobipy.quicksum((r_i[i] * x[i] for i in I)), GRB.MAXIMIZE)
    for i in I:
        model.addConstr(x[i] <= d_i[i], name=f'demand_{i}')
        model.addConstr(x[i] <= s_i[i], name=f'inventory_{i}')
    model.optimize()
    return model
m = solve_problem()
